ee:message.ee:set-payload:
					%dw 2.0
output application/java
var promptTemplate = readUrl("classpath://${prompt.amount.analysis.file}", "text/plain")
var step1 = (promptTemplate replace "{{amount}}" with (payload.amount as String)) as String
var processedPrompt = (step1 replace "{{description}}" with payload.description default "") as String
---
{
	prompt: processedPrompt,
	poData: payload
}

					%dw 2.0 output application/java
var promptTemplate = readUrl("classpath://${prompt.vendor.analysis.file}", "text/plain")
var step1 = (promptTemplate replace "{{vendorId}}" with (vars.originalPO.vendorId default "")) as String
var step2 = (step1 replace "{{description}}" with (vars.originalPO.description default "")) as String
var processedPrompt = (step2 replace "{{amount}}" with (vars.originalPO.amount as String default "0")) as String
---
{
	prompt: processedPrompt,
	poData: vars.originalPO
}

					%dw 2.0 output application/java
var historicalData = readUrl("classpath://${data.partner.history.file}", "application/json")
var vendorFilteredData = historicalData filter ($.vendorId == vars.originalPO.vendorId)
var promptTemplate = readUrl("classpath://${prompt.partner.history.analysis.file}", "text/plain")
var step1 = (promptTemplate replace "{{vendorId}}" with (vars.originalPO.vendorId default "")) as String
var step2 = (step1 replace "{{amount}}" with (vars.originalPO.amount as String default "0")) as String
var step3 = (step2 replace "{{poDate}}" with (vars.originalPO.poDate default "")) as String
var step4 = (step3 replace "{{description}}" with (vars.originalPO.description default "")) as String
var processedPrompt = (step4 replace "{{historicalData}}" with (write(vendorFilteredData, "application/json") default "[]")) as String
---
{
	prompt: processedPrompt,
	poData: vars.originalPO,
	historicalDataCount: sizeOf(vendorFilteredData)
}
